(function (global) {
    'use strict';

    var encoder = global.QRCode;
    if (!encoder || typeof encoder.create !== 'function') {
        console.error('The local QR matrix encoder must load before the QRCode renderer.');
        return;
    }

    function QRCode(container, options) {
        options = options || {};
        if (typeof container === 'string') container = document.getElementById(container);
        if (!container) throw new Error('A QR container element is required.');

        var width = Number(options.width) || 128;
        var height = Number(options.height) || 128;
        var quietZone = Math.max(0, Number(options.margin === undefined ? 4 : options.margin));
        var matrix = encoder.create(String(options.text || 'BIC-TAG'), {
            errorCorrectionLevel: 'M'
        }).modules;
        var moduleCount = matrix.size + quietZone * 2;
        var scale = Math.min(width, height) / moduleCount;
        var offsetX = (width - moduleCount * scale) / 2;
        var offsetY = (height - moduleCount * scale) / 2;
        var canvas = document.createElement('canvas');
        canvas.width = width;
        canvas.height = height;
        canvas.setAttribute('role', 'img');
        canvas.setAttribute('aria-label', 'Property tag QR code');

        var context = canvas.getContext('2d');
        if (!context) throw new Error('Canvas 2D rendering is unavailable.');
        context.fillStyle = options.colorLight || '#ffffff';
        context.fillRect(0, 0, width, height);
        context.fillStyle = options.colorDark || '#000000';
        for (var row = 0; row < matrix.size; row++) {
            for (var column = 0; column < matrix.size; column++) {
                if (!matrix.get(row, column)) continue;
                var left = Math.floor(offsetX + (column + quietZone) * scale);
                var top = Math.floor(offsetY + (row + quietZone) * scale);
                var right = Math.ceil(offsetX + (column + quietZone + 1) * scale);
                var bottom = Math.ceil(offsetY + (row + quietZone + 1) * scale);
                context.fillRect(left, top, right - left, bottom - top);
            }
        }

        container.replaceChildren(canvas);
        this._canvas = canvas;
    }

    global.QRCode = QRCode;
})(window);
